<?php
require __DIR__.'/config/database.php';function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){try{if(($_POST['action']??'')==='add'){$s=$pdo->prepare('INSERT INTO phong_thi(ma_phong,toa_nha,suc_chua) VALUES(?,?,?)');$s->execute([trim($_POST['ma_phong']),trim($_POST['toa_nha']),(int)$_POST['suc_chua']]);$msg='Đã thêm phòng thi.';}elseif(($_POST['action']??'')==='delete'){$s=$pdo->prepare('DELETE FROM phong_thi WHERE id=?');$s->execute([(int)$_POST['id']]);$msg='Đã xóa phòng thi.';}}catch(Throwable $e){$err='Không thực hiện được (có thể phòng đang được dùng trong ca thi): '.$e->getMessage();}}
$rows=$pdo->query('SELECT p.*, (SELECT COUNT(*) FROM ca_thi c WHERE c.phong_thi_id=p.id) so_ca FROM phong_thi p ORDER BY p.ma_phong')->fetchAll();
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Phòng thi - ExamFlow</title><link rel="stylesheet" href="assets/style.css"></head><body><div class="layout"><aside class="sidebar"><div class="brand">▦ ExamFlow</div><a href="index.php">Tổng quan</a><a href="students.php">Sinh viên</a><a href="courses.php">Học phần</a><a href="exams.php">Kỳ thi & ca thi</a><a class="active" href="rooms.php">Phòng thi</a><a href="results.php">Kết quả thi</a></aside><main class="main"><div class="top"><div><h1>Quản lý phòng thi</h1><div class="muted">Xem và thêm phòng thi.</div></div><a class="btn secondary" href="index.php">← Tổng quan</a></div><?php if($msg):?><div class="notice"><?=h($msg)?></div><?php endif?><?php if($err):?><div class="notice error"><?=h($err)?></div><?php endif?><div class="panel"><h2>Thêm phòng thi</h2><form method="post"><input type="hidden" name="action" value="add"><div class="formgrid"><div><label>Mã phòng</label><input name="ma_phong" required maxlength="15"></div><div><label>Tòa nhà</label><input name="toa_nha" required maxlength="50"></div><div><label>Sức chứa</label><input type="number" name="suc_chua" min="1" required></div></div><button class="btn">Thêm phòng</button></form></div><div class="panel"><h2>Danh sách phòng (<?=count($rows)?>)</h2><table><thead><tr><th>Mã phòng</th><th>Tòa nhà</th><th>Sức chứa</th><th>Số ca thi</th><th>Thao tác</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['ma_phong'])?></td><td><?=h($r['toa_nha'])?></td><td><?=h($r['suc_chua'])?></td><td><?=h($r['so_ca'])?></td><td><form method="post" onsubmit="return confirm('Xóa phòng này?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger">Xóa</button></form></td></tr><?php endforeach?></tbody></table></div></main></div></body></html>
